import{_ as s,o as t,c as a,a6 as r}from"./chunks/framework.DNkVJs23.js";const m=JSON.parse('{"title":"Confidentialité","description":"Confidentialité — Sapphire Star Codex","frontmatter":{"description":"Confidentialité — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/fr/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/fr/privacy/"}],["meta",{"property":"og:title","content":"Confidentialité | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Confidentialité — Sapphire Star Codex"}]]},"headers":[],"relativePath":"fr/privacy/index.md","filePath":"fr/privacy/index.md"}'),n={name:"fr/privacy/index.md"};function i(o,e,l,u,p,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to &quot;Confidentialité&quot;">​</a></h1><p>Entrée en vigueur : 31 octobre 2026. Dernière mise à jour du texte source : 10 novembre 2026. Traduction : 14 novembre 2026.</p><p>Cette politique couvre les applications iOS, Android et HarmonyOS de Sapphire Star Codex et ce site. Développeur : <strong>eurekaffeine (刘耀晨)</strong>. Contact : <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Les fonctions varient selon la plateforme ; aucun compte n’est nécessaire.</p><h2 id="donnees-locales" tabindex="-1">Données locales <a class="header-anchor" href="#donnees-locales" aria-label="Permalink to &quot;Données locales&quot;">​</a></h2><p>L’app conserve sur l’appareil les préférences de jeu, langue et apparence, l’historique de recherche et l’état de navigation, les favoris, les sets enregistrés, leurs noms et les inventaires de joyaux, talismans et armures. Ces données servent aux fonctions de l’app ; elles ne sont pas envoyées au développeur. Aucun service de compte ou de synchronisation cloud n’est exploité par le développeur.</p><h2 id="autorisations-et-collecte-automatique" tabindex="-1">Autorisations et collecte automatique <a class="header-anchor" href="#autorisations-et-collecte-automatique" aria-label="Permalink to &quot;Autorisations et collecte automatique&quot;">​</a></h2><p>L’app n’intègre aucun SDK publicitaire, de suivi, de statistiques d’usage ou d’envoi automatique de rapports de plantage. Les fonctions actuelles n’utilisent pas contacts, position, caméra, microphone ou photos et ne collectent pas d’identifiant publicitaire. Le système et les boutiques peuvent traiter leurs propres données d’installation ou de diagnostic ; les diagnostics transmis au développeur servent uniquement au dépannage.</p><h2 id="messages-et-services-externes" tabindex="-1">Messages et services externes <a class="header-anchor" href="#messages-et-services-externes" aria-label="Permalink to &quot;Messages et services externes&quot;">​</a></h2><p>Les courriels volontaires transmettent votre adresse, le message et les pièces jointes. Ils servent à répondre, résoudre les problèmes et traiter les demandes de confidentialité, pas au marketing. N’envoyez que les informations nécessaires. Gmail fournit la messagerie selon la <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">politique de Google</a>.</p><p>GitHub Pages héberge ce site et peut recevoir l’adresse IP et des informations techniques sur le navigateur : voir la <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">déclaration de GitHub</a>. Aucune statistique de visite, cookie publicitaire ou pixel de suivi n’est ajouté. La recherche est locale au navigateur, qui peut conserver les préférences. Les services externes appliquent leurs propres politiques et peuvent traiter des données hors de votre pays.</p><h2 id="contributions-et-sauvegardes" tabindex="-1">Contributions et sauvegardes <a class="header-anchor" href="#contributions-et-sauvegardes" aria-label="Permalink to &quot;Contributions et sauvegardes&quot;">​</a></h2><p>Alipay ou WeChat Pay traite les contributions selon ses propres conditions. Le site affiche seulement des codes statiques, sans SDK de paiement ni réception d’identifiants. Le développeur peut voir les informations fournies au bénéficiaire, telles que montant, date, nom affiché et note, pour vérifier les contributions et résoudre les problèmes. Leur conservation suit les règles de la plateforme et les obligations applicables. Les données de l’app peuvent aussi entrer dans les sauvegardes système ou cloud selon vos réglages ; le développeur ne peut ni lire ni supprimer ces sauvegardes.</p><h2 id="partage-conservation-et-suppression" tabindex="-1">Partage, conservation et suppression <a class="header-anchor" href="#partage-conservation-et-suppression" aria-label="Permalink to &quot;Partage, conservation et suppression&quot;">​</a></h2><p>Le développeur ne vend ni ne loue les données personnelles et ne les partage pas à des fins publicitaires. Les courriels passent par le fournisseur indiqué. Des informations effectivement détenues peuvent être communiquées si la loi l’exige ou à votre demande explicite.</p><p>Supprimez les données locales avec les fonctions de l’app ou les réglages système. Une désinstallation conservant les données ne les efface pas ; gérez les sauvegardes séparément, car elles peuvent restaurer ces données. Les préférences du site restent jusqu’à leur effacement ou leur nettoyage par le navigateur. Les messages sont conservés seulement pour le traitement, le suivi ou les obligations légales. Les prestataires gèrent leurs propres journaux et sauvegardes. Contactez-nous pour accéder aux informations envoyées, les corriger ou demander leur suppression, sous réserve des obligations légales ; le développeur ne peut pas accéder à distance aux données restées sur l’appareil.</p><h2 id="securite-mineurs-et-mises-a-jour" tabindex="-1">Sécurité, mineurs et mises à jour <a class="header-anchor" href="#securite-mineurs-et-mises-a-jour" aria-label="Permalink to &quot;Sécurité, mineurs et mises à jour&quot;">​</a></h2><p>Les mécanismes du système protègent le stockage local. Le site utilise HTTPS ; l’accès aux messages est limité aux besoins d’assistance et de confidentialité et utilise les protections du fournisseur de messagerie. L’app ne demande ni profil personnel ni date de naissance et ne cherche pas à collecter des données d’enfants. Un parent peut demander la suppression d’informations transmises par un enfant.</p><p>La politique et sa date évoluent avec les pratiques ; les changements importants sont annoncés sur le site ou dans les notes de mise à jour. Toute autorisation ou consentement nécessaire à une nouvelle fonction est demandé séparément ; cette politique ne constitue pas ce consentement.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const f=s(n,[["render",i]]);export{m as __pageData,f as default};
